svg.script:
function chunkStart(text, first, vertical) {
  let edges = [first, first + 1].map(i => {
    let extent = text.getExtentOfChar(i);
    return vertical ? extent.y : extent.x;
  });
  return Math.min(...edges);
}
for (let text of document.getElementsByTagName('text')) {
  let [first, second] = text.getAttribute('expected').split(' ').map(parseFloat);
  let vertical = text.hasAttribute('vertical');
  let description = (vertical ? 'vertical' : 'rtl') + ', text-anchor=' + text.getAttribute('text-anchor');
  promise_test(async t => {
    await document.fonts.load('20px Ahem');
    await document.fonts.ready;
    assert_approx_equals(chunkStart(text, 0, vertical), first, 0.5, 'first chunk');
    assert_approx_equals(chunkStart(text, 2, vertical), second, 0.5, 'second chunk');
  }, description);
}
